        double s = (double)sint / (double)steps;
        c[1] = b[0] * clip( s * PI/2 );
        c[2] = b[0] * cos ( s * PI/2 );
        x[0] = c[2]; y[0] = c[1]; xyiMax = max(xyiMax, 0);
        x[1] = -c[2]; y[1] = c[1]; xyiMax = max(xyiMax, 1);
