        x[3] = c[2]; y[3] = -c[1]; xyiMax = max(xyiMax, 3);
        x[4] = c[2]* 2; y[4] = c[1]* 2; xyiMax = max(xyiMax, 4);
        x[5] = c[2]*-2; y[5] = c[1]* 2; xyiMax = max(xyiMax, 5);
        x[6] = c[2]*-2; y[6] = c[1]*-2; xyiMax = max(xyiMax, 6);
        x[7] = c[2]* 2; y[7] = c[1]*-2; xyiMax = max(xyiMax, 7);
        draw(1, 5, pow(15*fft(s),.6), x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
