    a[0] = .1;  // Displacment X for each new instance
    a[1] = rnd(.8) + .1;  // Rotation speed
    a[2] = rnd(.5) + .1;  // 2nd rotation speed
    a[3] = rnd(.5) + .1;  // Radius of circle ( displacement before 2nd rotation
    a[4] = rnd(.4);  // Scaling speed
    a[5] = .6 + rnd(.4);  // Random darkness (usually white)

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[1];
