// Wave shape: CrossBall
// Macro:  Wave(CrossBall, "Thomas Geier", "ziggystar(at)gmx.de", "", 1)
// Source: pixel/WaveShapes.sky.h:686
// Author: Thomas Geier  <ziggystar(at)gmx.de>
// Steps=50  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_CrossBall(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(50);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .6;  // rotation speed
    a[1] = 0.9;  // size
    a[2] = .1*a[0];  // x-Rotation speed
    a[3] = .7*a[0];  // y-Rotation speed
    a[4] = .57*a[0];  // z-Rotation speed

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = cos(t*a[4])*sin(t*a[3])+sin(t*a[4])*sin(t*a[2])*cos(t*a[3]);  // x[1] of the rotated vector (x[1]/x[2]/x[3])
    b[1] = sin(t*a[4])*sin(t*a[3])-cos(t*a[4])*sin(t*a[2])*cos(t*a[3]);  // x[2]
    b[2] = sqrt(1-sqrt( pow(b[0],2) +pow(b[1],2)));
    b[3] = atan(b[1]/b[0]);
    b[4] = -sin(a[4]*t)*cos(a[2]*t);
    b[5] = cos(a[4]*t)*cos(a[2]*t);
    b[6] = sqrt(1-sqrt( pow(b[4],2) +pow(b[5],2)));
    b[7] = atan(b[5]/b[4]);
    b[8] = cos(a[4]*t)*cos(a[3]*t)-sin(a[4]*t)*sin(a[2]*t)*sin(a[3]*t);
    b[9] = sin(a[4]*t)*cos(a[3]*t)+cos(a[4]*t)*sin(a[2]*t)*sin(a[3]*t);
    b[10] = sqrt(1-sqrt( pow(b[8],2) + pow(b[9],2)));
    b[11] = atan(b[9]/b[8]);
    b[12] = .2 * pow(beat(),1.4);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sin(s*6.28);
        c[1] = cos(s*6.28);
        x[0] = a[1]*(c[1]*b[2]*cos(b[3])-c[0]*sin(b[3])); xyiMax = max(xyiMax, 0);
        y[0] = a[1]*(c[0]*cos(b[3])+c[1]*b[2]*sin(b[3]));
        x[1] = a[1]*(c[1]*b[6]*cos(b[7])-c[0]*sin(b[7])); xyiMax = max(xyiMax, 1);
        y[1] = a[1]*(c[0]*cos(b[7])+c[1]*b[6]*sin(b[7]));
        x[2] = a[1]*(c[1]*b[10]*cos(b[11])-c[0]*sin(b[11])); xyiMax = max(xyiMax, 2);
        y[2] = a[1]*(c[0]*cos(b[11])+c[1]*b[10]*sin(b[11]));
        x[3] = b[12]*(-b[8]+s*(2*b[8])); xyiMax = max(xyiMax, 3);
        y[3] = b[12]*(-b[9]+s*(2*b[9]));
        x[4] = b[12]*(-b[0]+s*(2*b[0])); xyiMax = max(xyiMax, 4);
        y[4] = b[12]*(-b[1]+s*(2*b[1]));
        x[5] = b[12]*(-b[4]+s*(2*b[4])); xyiMax = max(xyiMax, 5);
        y[5] = b[12]*(-b[5]+s*(2*b[5]));
        draw(1, 1, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

