    {
        double s = (double)sint / (double)steps;
        c[0] = a[0] + a[2] * s;
        x[0] = c[0] * cos( b[0] ); xyiMax = max(xyiMax, 0);
        y[0] = c[0] * sin( b[0] );
        draw(1, 1, 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(2) Density(1) Zoomable(5) Offsetable(1) Morphable(1)
    }
