    b[18] = wrap(t*b[2])*6.28;
    b[3] = 0.0005*cos(t*0.3);
    b[9] = cos(0.6 *t);
    b[19] = wrap(t*b[3])*6.28;
    b[4] = 0.0006*cos(t*0.2);
    b[10] = cos(0.1 *t);
    b[20] = wrap(t*b[4])*6.28;
    b[5] = 0.0004*cos(t*0.1);
    b[11] = cos(0.08*t);
    b[21] = wrap(t*b[5])*6.28;
    b[12] = cos(t*0.01);
    b[13] = cos(t*0.02);
    b[14] = cos(t*0.05);
