        x[3] = cos(b[19]+s*b[ 9]) * (b[15]+c[0]); xyiMax = max(xyiMax, 3);
        x[4] = cos(b[20]+s*b[10]) * (  0.6+c[0]); xyiMax = max(xyiMax, 4);
        x[5] = cos(b[21]+s*b[11]) * (  0.4+c[0]); xyiMax = max(xyiMax, 5);
