    double aspect = (1);
    a[0] = (flor(rnd(3))+3);
    a[1] = (rnd(4)+6);

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = (trwv(.7*t/(a[1])));  // Time
