        c[0] = b[1] * s;  // theta
        c[1] = cos( b[0] * c[0] ) + (.18 * mag( s ));  // r
        c[2] = c[1] * cos( c[0] + b[2] );
        c[3] = c[1] * sin( c[0] + b[2] / a[0]);
        x[0] = c[2]; xyiMax = max(xyiMax, 0);
        y[0] = c[3];
        x[1] = -c[2]; xyiMax = max(xyiMax, 1);
        y[1] = -c[3];
        draw(1, 1, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
