// Wave shape: ER_Rhythm_is_Deified
// Macro:  Wave(ER_Rhythm_is_Deified, "Erlend Robaye", "", "Thank you Magnus for the superb CD(The body gave you everything *****)", 1)
// Source: pixel/WaveShapes.sky.h:1163
// Author: Erlend Robaye
// Note:   Thank you Magnus for the superb CD(The body gave you everything *****)
// Steps=512  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(4) Density(3) Morphable(4)
// ==============================================================================
void wave_ER_Rhythm_is_Deified(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 4;  // Cut one line up into 4 parts)// therefore make 46 numbers) if one number is 1) all others are 0
    a[1] = 1/a[0];
    a[2] = .8 + rnd(.5);  // Width
    a[3] = .3 + rnd(.3);  // height
    a[4] = a[3]/2;  // Half the height
    a[5] = a[2]/2;
    a[6] = .6*a[3];
    a[7] = rnd(.4);  // Speed of rotation
    a[8] = 2*PI;
    a[9] = 3;
    a[10] = a[9] * ( .9 );  // This mixes up the total size
    a[11] = a[5]+.2;  // width to move left / right
    a[12] = a[4]+.4;  // height to move up / down
    a[13] = 4;
    a[14] = .04 + rnd(.04);  // Height of the upper and lower curve of the box
    a[15] = rnd( .4 ) + .1;  // Camera inclination change rate
    a[16] = 1.5 + rnd( 3 );  // Line thickness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[7];
    b[1] = cos( b[0] );
    b[2] = sin( b[0] );
    b[4] = sin( t * a[15] );
    b[5] = cos( t * a[15] );
    b[6] = log( 5 * beat() + 1 )*.05 - a[14];  // The bass in the curve

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sqwv( 8 * s - 1  );
        c[1] = sqwv( 8 * s - 3  );
        c[2] = sqwv( 8 * s - 5 );
        c[3] = sqwv( 8 * s - 7 );
        c[4] = s      *a[0];  // an s from 0 to 1 for first  part of line
        c[5] = (s-  a[1])*a[0];  // an s from 0 to 1 for second part of line
        c[6] = (s-2*a[1])*a[0];
        c[7] = (s-3*a[1])*a[0];
        c[9] = -a[5] +  a[2] * ( c[4] * c[0] + c[1] + (1-c[6]) * c[2] );
        c[10] = -a[4] +  b[6] * sin(PI*c[4]) * ( c[2] - c[0] ) + a[3] * ( c[7]*c[3] + c[5]*c[1] + c[2] );
        c[11] = -a[5] + (a[2]*s);
        c[12] = mag(s)*a[6]*sin(PI*s);
        c[13] = -b[1] * c[12] - b[2] * c[11];
        c[14] = b[1] * c[11] - b[2] * c[12];
        c[15] = -b[1] * c[10] - b[2] * c[9];
        c[16] = b[1] * c[9]  - b[2] * c[10];
        c[17] = c[14] * b[5];  // Y'(Y * b[5]
        c[18] = a[9] - c[14] * b[4];  // Z (PerspectiveDistortion - Y * b[4]
        c[19] = a[10] * c[13] / c[18];  // SizeMix * X  / Z
        c[20] = a[10] * c[17] / c[18];  // SizeMix * Y' / Z
        c[21] = c[16] * b[5];  // Y'(Y * b[5]
        c[22] = a[9] - c[16] * b[4];  // Z (PerspectiveDistortion - Y * b[4]
        c[23] = a[10] * c[15] / c[22];  // SizeMix * X  / Z
        c[24] = a[10] * c[21] / c[22];  // SizeMix * Y' / Z
        x[0] = a[11]+c[19]; y[0] = c[20]; xyiMax = max(xyiMax, 0);
        x[2] = a[11]+c[23]; y[2] = c[24]; xyiMax = max(xyiMax, 2);
        x[1] = c[19]-a[11]; y[1] = c[20]; xyiMax = max(xyiMax, 1);
        x[3] = c[23]-a[11]; y[3] = c[24]; xyiMax = max(xyiMax, 3);
        draw(1, a[16], 1, x, y, xyiMax);  // Meta() Reactive(3) Detail(4) Density(3) Morphable(4)
    }
}

