void wave_Hourglass(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(-1);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2*PI;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * .6;
    b[1] = .5 * cos( b[0] );
    b[2] = .5 * sin( b[0] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s * a[0];
        c[1] = mag(s) * .2 + .5;
        c[2] = s + .2;
        c[3] = cos( c[0] );
        c[4] = sin( c[0] );
        c[5] = .1 * mag(s);
        x[0] = 5 * c[5] + .5 * c[3] + b[1]; xyiMax = max(xyiMax, 0);
        y[0] = .5 * c[4] + b[2];
        x[1] = 5 * c[5] + .5 * c[3] - b[1]; xyiMax = max(xyiMax, 1);
        y[1] = .5 * c[4] - b[2];
        x[2] = c[5] + .12 * c[3]; xyiMax = max(xyiMax, 2);
        y[2] = c[5] + .12 * c[4];
        draw(0, 1, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: I_Declare
// Macro:  Wave(I_Declare, "", "", "Generator", 1)
// Source: pixel/WaveShapes.sky.h:1592
// Note:   Generator
// Steps=100*(3+ fmod(rnd(400),4) )  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_I_Declare(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(100*(3+ fmod(rnd(400),4) ));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .05 + rnd( .3 );
    a[5] = .05 + rnd( .3 );
    a[6] = 2 * PI / a[1];
    a[7] = 2 * tan( PI / a[1] );  // Calc inner radius of the polygon for a side of len 1
    a[1] = trnc( NumSSteps / 100 );
    a[2] = NumSSteps / a[1];
    a[3] = 4 + rnd( 7 );
    a[4] = a[3] * ( .4 + rnd( .5 ) );

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sin( t * a[5] );
    b[1] = cos( t * a[5] );
    b[2] = sin( t * a[0] );
    b[3] = cos( t * a[0] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[6] * trnc( s * a[1] );
        c[1] = a[7] * ( wrap( s * a[1] ) - .5 );
        c[2] = 1 + .55 * mag( s * a[1] );
        c[3] = c[2] * cos( c[0] ) - c[1] * sin( c[0] );
        c[4] = c[2] * sin( c[0] ) + c[1] * cos( c[0] );
        c[5] = c[3] * b[1] - c[4] * b[0];  // x
        c[6] = c[3] * b[0] + c[4] * b[1];  // y
        c[7] = c[6] * b[3];  // y
        c[8] = a[3] -  c[6] * b[2];
        x[0] = a[4] * c[5] / c[8]; xyiMax = max(xyiMax, 0);
        y[0] = a[4] * c[7] / c[8];
        draw(1, 3, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: Unknown
// Macro:  Wave(Unknown, "", "", "", 1)
// Source: pixel/WaveShapes.sky.h:1645
// Steps=sampleSlots()  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_Unknown(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(sampleSlots());
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .15;  // min size

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = trnc(6*beat())/2;  // shape based on beat
    b[1] = trnc(6*beat())/2;  // Add - abs(sin(t/4)) to the end of b[0] and - abs(sin(t/2)) to the end of b[1] and watch it morph!
    b[2] = .13 * beat();  // scale object based on beat

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = 2*PI*s;
        c[1] = .15*mag(s);  // Makes sections of shape move up to 20% based on magnitude at a certain point.
        x[0] = (a[0]+b[2]) * cos( 3*c[0] )+c[1]; xyiMax = max(xyiMax, 0);
        y[0] = (a[0]+b[2]) * sin( 4*c[0] )+c[1];
        draw(1, pow(8*abs(mag(s)),1.3), 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

