        x[6] = c[2]	+.8; y[6] = c[3]; xyiMax = max(xyiMax, 6);
        x[7] = c[2]; y[7] = c[3] + .7; xyiMax = max(xyiMax, 7);
        x[8] = c[2]; y[8] = c[3] - .7; xyiMax = max(xyiMax, 8);
        draw(3, 1, 1, x, y, xyiMax);
