// Wave shape: Miris_Ball
// Macro:  Wave(Miris_Ball, "Jeff Osborn", "jo009j(at)mail.rochester.edu", "")  ... Num(rnd(5) + 8)
// Source: pixel/WaveShapes.sky.h:1897
// Author: Jeff Osborn  <jo009j(at)mail.rochester.edu>
// Steps=num + (num - id)  Aspect=1  Instances(num)=rnd(5) + 8
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(1)
// NOTE(port): instance count set via Num(rnd(5) + 8) macro, not Wave()'s 5th argument
// NOTE(port): Steps/Aspect reference `id`, but the real engine evaluates
// them once per shape-selection inside a shared (non-per-instance) member,
// so only the LAST instance's (id == num-1) value actually takes effect.
// ==============================================================================
void wave_Miris_Ball(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(num + (num - id));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = rnd(0.3) + 0.1;  // Random initial radius
    a[1] = rnd(.9);  // This is used to calcluate the path the entire ball travels
    a[2] = rnd(.9);  // So is this
    a[3] = clip( .3 + rnd( .9 ) );  // Random pen darkness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[1];  // This helps make the circles spin..the dots) that is.  The dots spin _along_ the cirlce) this has nothing to do with the psuedo-3D motion  ")
    b[1] = sin(t * a[1]);  // The path of the entire ball
    b[2] = sin(t * a[2]);  // Same
    b[3] = id / num;  // The unique ID of each pair of circles.
    b[4] = b[3] * a[0] * sin(.8 * t);
    b[5] = b[3] * a[0] * cos(.8 * t);
    b[6] = (a[0] - (a[0] * b[3])) * cos(.8 * t);  // radius in Y) after calculations and spinning
    b[7] = (a[0] - (a[0] * b[3])) * sin(.8 * t);  // radius in X) after calculations and spinning

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = b[7] * cos( s * 6.2831853 + b[0] ) + b[1];
        c[1] = b[6] * sin( s * 6.2831853 + b[0] ) + b[2];
        x[0] = ( c[0] + b[5] ) * .54; xyiMax = max(xyiMax, 0);
        y[0] = ( c[1] + b[4] ) * .84;
        x[1] = ( c[0] - b[5] ) * .54; xyiMax = max(xyiMax, 1);
        y[1] = ( c[1] - b[4] ) * .84;
        draw(0, 1, a[3], x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(1)
    }
}

