    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        x[0] = (2 * s - 1) + (b[1] * (pow(-1,id))); xyiMax = max(xyiMax, 0);
        y[0] = b[2] * (pow(-1,id)) + (0.04 * (pow(-1,id)));
        draw(0, a[3], 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
