        x[0] = (sin(c[0] * b[1])) * 0.90 + sin(c[0] * 5) * 0.075; xyiMax = max(xyiMax, 0);
        y[0] = (cos(c[0] * b[2])) * 0.90 + cos(c[0] * 6) * 0.075;
