// ==============================================================================
void wave_Pyramidion_Particle(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(5);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .70;  // Length of one rib of square
    a[1] = 4;  // Number of interval in one (x)y) couple
    a[2] = a[0] + a[0];
    a[3] = a[0] + a[2];
    a[4] = rnd(1) + 1;  // Rotation speed
    a[5] = 1/a[1];  // Range of interval of s
    a[6] = 6;
    a[7] = a[6] * ( .9 );
    a[8] = PI/2 + rnd( .4 ) + .05;  // View point of camera (PI/2 ( flat) + above - under )
    a[9] = sin( a[8] );
    a[10] = cos( a[8] );
    a[11] = .083;
    a[12] = 1    -a[11];  // scaling factor next square
    a[13] = a[12]-a[11];
    a[14] = a[13]-a[11];
    a[15] = a[14]-a[11];
    a[16] = a[15]-a[11];
    a[17] = a[16]-a[11];
    a[18] = a[17]-a[11];
    a[19] = a[18]-a[11];
    a[20] = a[19]-a[11];
    a[21] = a[20]-a[11];
    a[22] = a[21]-a[11];
    a[25] = .05;  // Y increase next square
    a[23] = rnd(.6) + .1;
    a[24] = 0;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = -a[4] * t;
    b[1] = cos( b[0] );  // rotate the triangle itself clockwise
    b[2] = sin( b[0] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = cos( 2*PI*s + .18 * t );  // X
        c[1] = sin( 2*PI*s + .18 * t );  // Y
        c[2] = c[1] * a[10];  // Y'(     Y * a[10]
        c[3] = a[6] - c[1] * a[9];  // Z (a[6] - Y * a[9]
        c[4] = a[7] * c[0] / c[3];  // a[7] * X  / Z
        c[5] = a[7] * c[2] / c[3] - .28;  // a[7] * Y' / Z
        x[0] = a[13]*c[4]; y[0] = a[13]*c[5]; xyiMax = max(xyiMax, 0);
        x[1] = a[14]*c[4]; y[1] = a[14]*c[5] +   a[25]; xyiMax = max(xyiMax, 1);
        x[2] = a[15]*c[4]; y[2] = a[15]*c[5] + 2*a[25]; xyiMax = max(xyiMax, 2);
        x[3] = a[16]*c[4]; y[3] = a[16]*c[5] + 3*a[25]; xyiMax = max(xyiMax, 3);
        x[4] = a[17]*c[4]; y[4] = a[17]*c[5] + 4*a[25]; xyiMax = max(xyiMax, 4);
        x[5] = a[18]*c[4]; y[5] = a[18]*c[5] + 5*a[25]; xyiMax = max(xyiMax, 5);
        x[6] = a[19]*c[4]; y[6] = a[19]*c[5] + 6*a[25]; xyiMax = max(xyiMax, 6);
        x[7] = a[20]*c[4]; y[7] = a[20]*c[5] + 7*a[25]; xyiMax = max(xyiMax, 7);
        x[8] = a[21]*c[4]; y[8] = a[21]*c[5] + 8*a[25]; xyiMax = max(xyiMax, 8);
        x[9] = a[22]*c[4]; y[9] = a[22]*c[5] + 9*a[25]; xyiMax = max(xyiMax, 9);
        draw(1, 1, a[23], x, y, xyiMax);  // Meta() Reactive(1) Detail(4) Density(4)
    }
}

