// Wave shape: Quad_Sweep
// Macro:  Wave(Quad_Sweep, "", "", "", 1)
// Source: pixel/WaveShapes.sky.h:2353
// Steps=100  Aspect=1  Instances(num)=1
// ==============================================================================
void wave_Quad_Sweep(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(100);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .7 + rnd( 1.1 );  // Choose rand rotation rate

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = cos( t * a[0] );
    b[1] = sin( t * a[0] );
    b[2] = .25 * cos(.5/(t*a[0]));
    b[3] = .25 * sin(.5/(t*a[0]));
    b[4] = .25 * cos(.5*(t*a[0]));
    b[5] = .25 * sin(.5*(t*a[0]));

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = mag( s ) * 0.4 * s;
        c[1] = c[0] * 4.5;
        c[2] = -b[4]*s    + b[5]*c[1] + .5;
        c[3] = b[4]*c[1] - b[5]*s    + .5;
        c[4] = b[4]*s    - b[5]*c[1] + .5;
        c[5] = -b[4]*c[1] + b[5]*s    + .5;
        c[6] = -b[2]*s    + b[3]*c[1] + .5;
        c[7] = b[2]*c[1] - b[3]*s    + .5;
        c[8] = b[2]*s    - b[3]*c[1] + .5;
        c[9] = -b[2]*c[1] + b[3]*s    + .5;
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = c[4]; y[1] = c[5]; xyiMax = max(xyiMax, 1);
        x[2] = c[6]; y[2] = c[7]; xyiMax = max(xyiMax, 2);
        x[3] = c[8]; y[3] = c[9]; xyiMax = max(xyiMax, 3);
        x[4] = c[2]-1; y[4] = c[3]; xyiMax = max(xyiMax, 4);
        x[5] = c[4]-1; y[5] = c[5]; xyiMax = max(xyiMax, 5);
        x[6] = c[6]-1; y[6] = c[7]; xyiMax = max(xyiMax, 6);
        x[7] = c[8]-1; y[7] = c[9]; xyiMax = max(xyiMax, 7);
        x[8] = c[2]-1; y[8] = c[3]-1; xyiMax = max(xyiMax, 8);
        x[9] = c[4]-1; y[9] = c[5]-1; xyiMax = max(xyiMax, 9);
        x[10] = c[6]-1; y[10] = c[7]-1; xyiMax = max(xyiMax, 10);
        x[11] = c[8]-1; y[11] = c[9]-1; xyiMax = max(xyiMax, 11);
        x[12] = c[2]; y[12] = c[3]-1; xyiMax = max(xyiMax, 12);
        x[13] = c[4]; y[13] = c[5]-1; xyiMax = max(xyiMax, 13);
        x[14] = c[6]; y[14] = c[7]-1; xyiMax = max(xyiMax, 14);
        x[15] = c[8]; y[15] = c[9]-1; xyiMax = max(xyiMax, 15);
        draw(1, 1, 1, x, y, xyiMax);
    }
}

