    int    steps  = (int)(40);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = t;
    a[1] = .3;
    a[2] = .03 * ( 1 + rnd( 4 ) );  // The width of each scope
