// ==============================================================================
// Wave shape: RipplingSpiral
// Macro:  Wave(RipplingSpiral, "Erlend Robaye", "erlend(at)vt4.net", "", 1)
// Source: pixel/WaveShapes.sky.h:2540
// Author: Erlend Robaye  <erlend(at)vt4.net>
// Steps=rnd( 120 ) + 20  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(4) Density(3)
// ==============================================================================
void wave_RipplingSpiral(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(rnd( 120 ) + 20);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2*PI;
    a[1] = 3*a[0];
    a[2] = 1.5;
    a[3] = 6;
    a[4] = a[3] * ( .9 );
    a[5] = PI/2;
    a[6] = .3;
    a[7] = -.8;
    a[8] = abs(2*a[7]) - .2;  // Factor to increase highest ID with to get max Y
    a[9] = rnd(.2) + .2;  // Rotation-wobble speed of 3D-spiral
    a[10] = a[5] + .4;  // Camera inclination angle
    a[11] = .8 + rnd(.3);  // Pen is dark most of the time

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[6]*t;
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);
    b[3] = sin( a[10] );
    b[4] = cos( a[10] );
    b[5] = t*a[9];
    b[6] = cos(b[5]);
    b[7] = sin(b[5]);
    b[8] = (t * b[7] * .00003) - a[5];
    b[9] = cos(b[8]);
    b[10] = sin(b[8]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s * a[2] * cos( s * a[1] );  // X
        c[1] = s * a[2] * sin( s * a[1] );  // Y
        c[2] = -b[1]*c[1]-b[2]*c[0];  // Rotated X
        c[3] = b[1]*c[0]-b[2]*c[1];  // Rotated Y
        c[4] = c[3] * b[4];  // Y'(          Y * cos(camera)
        c[5] = a[3] - c[3] * b[3];  // Z (Distort - Y * sin(camera)
        c[6] = a[4] * c[2] / c[5];  // SizeMix * X  / Z
        c[7] = a[4] * c[4] / c[5];  // SizeMix * Y' / Z
        c[8] = -b[9] * c[7] - b[10] * c[6];
        c[9] = b[9] * c[6] - b[10] * c[7];
        x[0] = c[8]; xyiMax = max(xyiMax, 0);
        y[0] = c[9] + (sin(t + s * NumSSteps * .2) * .3*s);  // Y displacement down
        c[10] = 11-((c[5]-5)*9);  // Width of particle depends on Z depth
        draw(0, c[10], a[11], x, y, xyiMax);  // Meta() Reactive(1) Detail(4) Density(3)
    }
}

