        x[15] = 0.6; y[15] = a[0]*s*(fft(0.2 ) + fft(0.8 )) - 1; xyiMax = max(xyiMax, 15);
        x[16] = 0.7; y[16] = a[0]*s*(fft(0.15) + fft(0.85)) - 1; xyiMax = max(xyiMax, 16);
        x[17] = 0.8; y[17] = a[0]*s*(fft(0.1 ) + fft(0.9 )) - 1; xyiMax = max(xyiMax, 17);
        x[18] = 0.9; y[18] = a[0]*s*(fft(0.05) + fft(0.95)) - 1; xyiMax = max(xyiMax, 18);
        x[19] = 1.0; y[19] = a[0]*s*(fft(0.0 ) + fft(1.00)) - 1; xyiMax = max(xyiMax, 19);
        c[0] = 2 * sin (s) + 0.1;
