// ==============================================================================
// Wave shape: Snake
// Macro:  Wave(Snake, "Erlend Robaye", "", "", 1)
// Source: pixel/WaveShapes.sky.h:2903
// Author: Erlend Robaye
// Steps=25  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Snake(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(25);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2*PI/3;
    a[1] = rnd(.6)+.3;  // Amplitude
    a[2] = rnd(1) + .3;  // Sine move speed
    a[3] = rnd(.3) + .4;  // radius
    a[4] = .9;  // Scaling factor next
    a[5] = rnd( 5 ) + 1;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    // (no B() frame terms)

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s*a[0]+t*.3;
        c[1] = a[3] + (sin(s*5*PI+t*2) * .05);
        c[2] = c[1] * cos(c[0]);
        c[3] = c[1] * sin(c[0]);
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = a[4]*c[2]; y[1] = a[4]*c[3]; xyiMax = max(xyiMax, 1);
        x[2] = a[4]*a[4]*c[4]; y[2] = a[4]*a[4]*c[5]; xyiMax = max(xyiMax, 2);
        draw(0, a[5], 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

// ==============================================================================
// Wave shape: SnakePit
// Macro:  Wave(SnakePit, "Erlend Robaye", "", "", 1)
// Source: pixel/WaveShapes.sky.h:2928
// Author: Erlend Robaye
// Steps=512  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
// ==============================================================================
void wave_SnakePit(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 1.6;
    a[1] = t;
    a[2] = .05 + rnd( .15 );  // Rotation Rate

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * a[2];
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);
    b[3] = b[0] + (2 * PI / 3);
    b[4] = cos( b[3] );
    b[5] = sin( b[3] );
    b[6] = b[0] + (4 * PI / 3);
    b[7] = cos( b[6] );
    b[8] = sin( b[6] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = .25 * sin(s * PI * a[0]) + mag(s) * .2;
        c[1] = s * a[0];
        x[0] = - b[1]*c[1] - b[2]*c[0]; xyiMax = max(xyiMax, 0);
        y[0] = b[1]*c[0] - b[2]*c[1];
        x[1] = - b[4]*c[1] - b[5]*c[0]; xyiMax = max(xyiMax, 1);
        y[1] = b[4]*c[0] - b[5]*c[1];
        x[2] = - b[7]*c[1] - b[8]*c[0]; xyiMax = max(xyiMax, 2);
        y[2] = b[7]*c[0] - b[8]*c[1];
        draw(1, 2, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

