    b[1] = sin((t-a[0])/a[1]*3.14*4)*.4;
    b[2] = b[0]-id/num;  // Y
    b[3] = id/num*6.28;
    b[4] = cos(b[3])*b[0];
    b[5] = sin(b[3])*b[0];

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
