// Wave shape: Spinning_Cube
// Macro:  Wave(Spinning_Cube, "Thomas Geier", "ziggystar(at)gmx.de", "Spinning Tetraeder", 1)
// Source: pixel/WaveShapes.sky.h:3183
// Author: Thomas Geier  <ziggystar(at)gmx.de>
// Note:   Spinning Tetraeder
// Steps=2  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(2) Density(3)
// ==============================================================================
void wave_Spinning_Cube(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(2);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = .8;  // This is the size of the cube
    a[1] = 1 + rnd( 5 );  // Cube line width
    a[2] = clip( .6 + rnd( 1 ) );  // Cube intensity

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sin( .4 * t );
    b[1] = cos( .4 * t );
    b[2] = .5*b[1]-.5*b[0];
    b[3] = .5*b[1]-b[0]*(-.5*b[1]-.5*b[0]);
    b[4] = .5*b[1]+.5*b[0];
    b[5] = .5*b[1]-b[0]*(.5*b[1]-.5*b[0]);
    b[6] = -.5*b[1]+.5*b[0];
    b[7] = .5*b[1]-b[0]*(.5*b[1]+.5*b[0]);
    b[8] = -.5*b[1]-.5*b[0];
    b[9] = -.5*b[1]-b[0]*(-.5*b[1]+.5*b[0]);
    b[10] = .5*b[1]-.5*b[0];
    b[11] = -.5*b[1]-b[0]*(-.5*b[1]-.5*b[0]);
    b[12] = .5*b[1]+.5*b[0];
    b[13] = -.5*b[1]-b[0]*(.5*b[1]-.5*b[0]);
    b[14] = -.5*b[1]+.5*b[0];
    b[15] = -.5*b[1]-b[0]*(.5*b[1]+.5*b[0]);
    b[17] = -.5*b[1]-.5*b[0];
    b[18] = .5*b[1]-b[0]*(-.5*b[1]+.5*b[0]);
    b[16] = 1;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = pos(sgn(.5-s))*a[0]*b[16];
        c[1] = pos(sgn(-.5+s))*a[0]*b[16];
        x[0] = c[0]*b[17] + c[1]*b[ 2]; y[0] = c[0]*b[18] + c[1]*b[ 3]; xyiMax = max(xyiMax, 0);
        x[1] = c[0]*b[ 2] + c[1]*b[ 4]; y[1] = c[0]*b[ 3] + c[1]*b[ 5]; xyiMax = max(xyiMax, 1);
        x[2] = c[0]*b[ 4] + c[1]*b[ 6]; y[2] = c[0]*b[ 5] + c[1]*b[ 7]; xyiMax = max(xyiMax, 2);
        x[3] = c[0]*b[ 6] + c[1]*b[17]; y[3] = c[0]*b[ 7] + c[1]*b[18]; xyiMax = max(xyiMax, 3);
        x[4] = c[0]*b[ 8] + c[1]*b[17]; y[4] = c[0]*b[ 9] + c[1]*b[18]; xyiMax = max(xyiMax, 4);
        x[5] = c[0]*b[10] + c[1]*b[ 2]; y[5] = c[0]*b[11] + c[1]*b[ 3]; xyiMax = max(xyiMax, 5);
        x[6] = c[0]*b[12] + c[1]*b[ 4]; y[6] = c[0]*b[13] + c[1]*b[ 5]; xyiMax = max(xyiMax, 6);
        x[7] = c[0]*b[14] + c[1]*b[ 6]; y[7] = c[0]*b[15] + c[1]*b[ 7]; xyiMax = max(xyiMax, 7);
        x[8] = c[0]*b[ 8] + c[1]*b[10]; y[8] = c[0]*b[ 9] + c[1]*b[11]; xyiMax = max(xyiMax, 8);
        x[9] = c[0]*b[10] + c[1]*b[12]; y[9] = c[0]*b[11] + c[1]*b[13]; xyiMax = max(xyiMax, 9);
        x[10] = c[0]*b[12] + c[1]*b[14]; y[10] = c[0]*b[13] + c[1]*b[15]; xyiMax = max(xyiMax, 10);
        x[11] = c[0]*b[14] + c[1]*b[ 8]; y[11] = c[0]*b[15] + c[1]*b[ 9]; xyiMax = max(xyiMax, 11);
        draw(1, a[1], a[2], x, y, xyiMax);  // Meta() Reactive(1) Detail(2) Density(3)
    }
}

