// Wave shape: Spinning_Tetra
// Macro:  Wave(Spinning_Tetra, "Andy O'Meara", "", "Spinning plane")  ... Num(1 + rnd( 7 ))
// Source: pixel/WaveShapes.sky.h:3319
// Author: Andy O'Meara
// Note:   Spinning plane
// Steps=4  Aspect=1  Instances(num)=1 + rnd( 7 )
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(2)
// NOTE(port): instance count set via Num(1 + rnd( 7 )) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Spinning_Tetra(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(4);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 0;
    a[1] = sin( - 3.14 * .3 );
    a[2] = cos( - 3.14 * .3 );
    a[5] = .2 + rnd( .5 );  // Choose a y'-axis rotation speed
    a[7] = .3 + rnd( .5 );  // Choose a x'-axis rotation speed
    a[8] = cos( 109.471200377 * PI / 180 );
    a[6] = sin( 109.471200377 * PI / 180 );
    a[3] = 10;
    a[4] = a[3] * ( .3 + rnd( .6 ) );  // This mixes up the total scale
    a[9] = .10 + rnd( .15 );  // Random length of coincident verticies..

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sin( t * a[5] );
    b[1] = cos( t * a[5] );
    b[2] = sin( t * a[7] );
    b[3] = cos( t * a[7] );
    b[4] = ( 1 + a[9] * id ) * a[4];

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sqwv( 100 * ( s - .9999 ) );
        c[1] = a[6] * ( 1 - c[0] ) * cos( s * 6.283185 );  // x') x
        c[2] = a[6] * ( 1 - c[0] ) * sin( s * 6.283185 );  // y'
        c[3] = - c[0] - ( 1 - c[0] ) * a[8];  // z' -- vertex 4 is at (0)0)1)
        c[4] = c[3] * b[1] - c[1] * b[0];  // new x'
        c[5] = c[3] * b[0] + c[1] * b[1];  // new z'
        c[6] = c[2] * b[3] - c[5] * b[2];  // new y'
        c[7] = c[2] * b[2] + c[5] * b[3];  // new z'
        c[8] = c[6] * a[2] + c[7] * a[1];
        c[9] = c[7] * a[2] - c[6] * a[1] + a[3];  // z
        x[0] = b[4] * c[4] / c[9]; xyiMax = max(xyiMax, 0);
        y[0] = b[4] * c[8] / c[9];
        draw(0, 13-2*id, 1, x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(2)
    }
}

