    {
        double s = (double)sint / (double)steps;
        c[0] = beat() * 0.07 + a[1] + id * a[0];  // radius
        c[1] = s * 6.28318530 + b[0];
        c[2] = c[0] * cos( c[1] );
        c[3] = c[0] * sin( c[1] );
        x[0] = c[2]; xyiMax = max(xyiMax, 0);
        y[0] = c[3];
        draw(1, 1, a[2], x, y, xyiMax);  // Meta() Reactive(2) Detail(3) Density(3) Morphable(2)
    }
