// Author: Erlend Robaye  <erlend(at)vt4.net>
// Steps=150  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3)
// ==============================================================================
void wave_Typhoon(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(150);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2*PI;  // 1 circle circumferance
    a[1] = 5*a[0];  // Spiral x times around
    a[2] = .8;
    a[3] = 6;
    a[4] = a[3]*.9;
    a[5] = PI/2;  // Flat point of camera
    a[6] = .7;
    a[7] = -.8;  // MiNumum Y of 3D spiral
    a[8] = abs(2*a[7])-.2;  // Factor to increase highest ID with to get max Y
    a[9] = rnd(.2) + .2;  // Speed of X displacement
    a[10] = .5;  // Max X displacement
    a[11] = a[5] + .3;  // View point of camera (PI/2 ( flat) + above - under )
    a[12] = .6 + rnd(.4);  // Random darkness

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[6]*t;
    b[1] = cos(b[0]);
    b[2] = sin(b[0]);
    b[3] = sin( a[11] );
    b[4] = cos( a[11] );
    b[5] = t*a[9];
    b[6] = cos(b[5]);
    b[7] = sin(b[5]);
    b[8] = (t * b[7] * .000005) - a[5];
    b[9] = cos(b[8]);
    b[10] = sin(b[8]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = s;
        c[1] = c[0] * a[1];
        c[2] = cos(c[1]);  // X
        c[3] = sin(c[1]);  // Y
        c[4] = c[0] * a[2];  // Scaling factor
        c[5] = c[4] * c[2];
        c[6] = c[4] * c[3];
        c[7] = -b[1]*c[6]-b[2]*c[5];  // Rotated X
        c[8] = b[1]*c[5]-b[2]*c[6];  // Rotated Y
        c[9] = c[8] * b[4];  // Y'(          Y * cos(camera)
        c[10] = a[3]  - c[8] * b[3];  // Z (Distort - Y * sin(camera)
        c[11] = a[4] * c[7] / c[10];
        c[12] = a[4] * c[9] / c[10] + c[0] * a[8];  // SizeMix * Y' / Z) add Y per ID
        c[13] = -b[9] * c[12] - b[10] * c[11];
        c[14] = b[9] * c[11] - b[10] * c[12];
        x[0] = c[13] + b[7] * a[10]; xyiMax = max(xyiMax, 0);  // X displacement in time
        y[0] = c[14] + a[7];
        draw(0, 1, a[12], x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3)
    }
}

