// Wave shape: Drop_and_Scatter
// Macro:  Wave(Drop_and_Scatter, "Ted", "", "Frame Fall")  ... Num(rnd( 3 ) + rnd( 3 ) + rnd( 3 ) + 6)
// Source: pixel/WaveShapes.sky.h:4744
// Author: Ted
// Note:   Frame Fall
// Steps=4 + rnd( 4 )  Aspect=1  Instances(num)=rnd( 3 ) + rnd( 3 ) + rnd( 3 ) + 6
// Author metadata tags (unused by engine, informational): Meta() Reactive(1) Detail(3) Density(3) Morphable(1) Zoomable(1)
// NOTE(port): instance count set via Num(rnd( 3 ) + rnd( 3 ) + rnd( 3 ) + 6) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Drop_and_Scatter(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(4 + rnd( 4 ));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2 * PI;
    a[1] = sqrt( 2 );
    a[2] = t;
    a[3] = rnd(1);
    a[4] = rnd(2  ) + 1;
    a[5] = rnd(.05) + .025;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = pos( t - a[2] - id * a[4] );
    b[1] = a[5] * pow(b[0],2);
    b[2] = a[1] * ( 0 + .1 / ( b[1] + .01 ) );  // scaling
    b[3] = seed( id * a[3] ) * 0 + rnd( a[0] );
    b[4] = rnd( a[0] );
    b[5] = 2 * cos( b[0] );
    b[6] = sgn( rnd( 2 ) - 1 );
    b[7] = rnd( a[0] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[0] * wrap(s + pow(b[1],2)) + .785398163;
        x[0] = b[2] * (cos(c[0])      + b[5]*cos(b[7])) + b[1]*.5*cos(b[1]+b[4]); xyiMax = max(xyiMax, 0);
        y[0] = b[2] * (sin(b[6]*c[0]) + b[5]*sin(b[7])) + b[1]*.5*sin(b[1]+b[3]);
        draw(2, b[2]*6, sqwv(b[0]/(4*PI)), x, y, xyiMax);  // Meta() Reactive(1) Detail(3) Density(3) Morphable(1) Zoomable(1) Offsetable(1)
    }
}

