// Steps=450  Aspect=1  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(2) Detail(3) Density(3) Morphable(1) Zoomable(4)
// NOTE(port): instance count set via Num(1) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Fern(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(450);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 166;
    a[1] = 7563;
    a[2] = 8757;
    a[3] = 10000;
    a[4] = 0;
    a[5] = 0;
    a[6] = 0;  // 1abe
    a[7] = 0;
    a[8] = .16;
    a[9] = 0;  // 1cdf
    a[10] = .85;
    a[11] = .04;
    a[12] = 0;  // 2abe
    a[13] = -.04;
    a[14] = .85;
    a[15] = 1.6;  // 2cdf
    a[16] = .2;
    a[17] = -.26;
    a[18] = 0;  // 3abe
    a[19] = .23;
    a[20] = .22;
    a[21] = 1.6;  // 3cdf
    a[22] = -.15;
    a[23] = .28;
    a[24] = 0;  // 4abe
    a[25] = .26;
    a[26] = .24;
    a[27] = .44;  // 4cdf
    a[28] = cos(4*PI/5);
    a[29] = sin(4*PI/5);
    a[30] = .4 + rnd(.55);  // Pen

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = .055 + .04 * beat();

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = flor(rnd( 10000 ) );
        c[1] = sqwv(c[0]/a[0] + .01 );
        c[2] = sqwv(c[0]/a[1] + .01 ) - c[1];
        c[3] = sqwv(c[0]/a[2] + .01 ) - c[1] - c[2];
        c[4] = sqwv(c[0]/a[3] + .01 ) - c[1] - c[2] - c[3];
        c[5] = c[1]*(a[ 4]*c[7] + a[ 5]*c[8] + a[ 6]) 
		+ c[2]*(a[10]*c[7] + a[11]*c[8] + a[12]) 
		+ c[3]*(a[16]*c[7] + a[17]*c[8] + a[18]) 
		+ c[4]*(a[22]*c[7] + a[23]*c[8] + a[24]);
        c[6] = c[1]*(a[ 7]*c[7] + a[ 8]*c[8] + a[ 9]) 
		+ c[2]*(a[13]*c[7] + a[14]*c[8] + a[15]) 
		+ c[3]*(a[19]*c[7] + a[20]*c[8] + a[20]) 
		+ c[4]*(a[25]*c[7] + a[26]*c[8] + a[27]);
        c[7] = c[5];
        c[8] = c[6];
        c[9] = b[0] * ( c[5] * a[28]  -  c[6] * a[29] );
        c[10] = b[0] * ( c[6] * a[28]  +  c[5] * a[29] );
        c[11] = flor( exp( rnd( 3.1 ) - 2 ) ) + 2;  // Pen
        x[0] = c[9]; y[0] = c[10]; xyiMax = max(xyiMax, 0);
        x[1] = -c[9]; y[1] = -c[10]; xyiMax = max(xyiMax, 1);
        draw(0, c[11], a[30], x, y, xyiMax);  // Meta() Reactive(2) Detail(3) Density(3) Morphable(1) Zoomable(4) Offsetable(4) SelfSym(5) RotaSym(4)
    }
}

