// Wave shape: Fireflies
// Macro:  Wave(Fireflies, "Ted", "", "Orbiting Stars", 1)
// Source: pixel/WaveShapes.sky.h:4832
// Author: Ted
// Note:   Orbiting Stars
// Steps=55  Aspect=0  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(4) Density(3) Morphable(1)
// ==============================================================================
void wave_Fireflies(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(55);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = t;
    a[1] = .08;
    a[2] = flor( rnd( 2 ) + 2 );  // Number of star points (*2)
    a[3] = rnd( .05 ) + .025;
    a[4] = .0002;
    a[5] = rnd(     PI );
    a[6] = rnd(   - PI );
    a[7] = rnd( 2 * PI );
    a[8] = rnd( 2 * PI );
    a[9] = rnd( 2 * PI );
    a[10] = rnd( 2 * PI );
    a[11] = rnd( 1 );
    a[12] = rnd( 1 );
    a[13] = rnd( 1 );
    a[14] = rnd( 1 ) - .5;
    a[15] = rnd( 1 ) - .5;
    a[16] = rnd( 1 ) - .5;
    a[17] = a[11] * cos( a[5] );
    a[18] = a[11] * sin( a[5] );
    a[19] = a[12] * cos( a[6] );
    a[20] = a[12] * sin( a[6] );
    a[21] = a[13] * cos( a[7] );
    a[22] = a[13] * sin( a[7] );
    a[23] = a[14] * cos( a[8] );
    a[24] = a[14] * sin( a[8] );
    a[25] = a[15] * cos( a[9] );
    a[26] = a[15] * sin( a[9] );
    a[27] = a[16] * cos( a[10] );
    a[28] = a[16] * sin( a[10] );
    a[29] = .3 + rnd( .5 );
    a[30] = NumSSteps * PI;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sqwv((t - a[0])*60);  // initializer
    b[1] = b[1] + b[0]*a[23] + (1 - b[0])*(b[16] + b[18]);  // movementvector
    b[2] = b[2] + b[0]*a[24] + (1 - b[0])*(b[17] + b[19]);
    b[3] = wrap(b[3] + b[0]*a[17] + a[4]*b[1]);  // iterativeXpos
    b[4] = wrap(b[4] + b[0]*a[18] + a[4]*b[2]);  // iterativeYpos
    b[5] = b[5] + b[0]*a[25] + (1 - b[0])*( - b[20] - b[16]);
    b[6] = b[6] + b[0]*a[26] + (1 - b[0])*( - b[21] - b[17]);
    b[7] = wrap(b[7] + b[0]*a[19] + a[4]*b[5]);
    b[8] = wrap(b[8] + b[0]*a[20] + a[4]*b[6]);
    b[9] = b[9] + b[0]*a[27] + (1 - b[0])*(b[20] - b[18]);
    b[10] = b[10] + b[0]*a[28] + (1 - b[0])*(b[21] - b[19]);
    b[11] = wrap(b[11] + b[0]*a[21] + a[4]*b[9]);
    b[12] = wrap(b[12] + b[0]*a[22] + a[4]*b[10]);
    b[13] = sqrt(pow(b[ 7]-b[3],2) + pow(b[ 8]-b[4],2) + a[3]);
    b[14] = sqrt(pow(b[11]-b[3],2) + pow(b[12]-b[4],2) + a[3]);  // distances
    b[15] = sqrt(pow(b[11]-b[7],2) + pow(b[12]-b[8],2) + a[3]);
    b[16] = pow(a[1]/b[13],2)*((b[7] - b[3])/b[13]);  // gravforce*cos[i.e.x/r]
    b[17] = pow(a[1]/b[13],2)*((b[8] - b[4])/b[13]);  // gravforce*sin[i.e.y/r]
    b[18] = pow(a[1]/b[14],2)*((b[11] - b[3])/b[14]);
    b[19] = pow(a[1]/b[14],2)*((b[12] - b[4])/b[14]);
    b[20] = pow(a[1]/b[15],2)*((b[7] - b[11])/b[15]);
    b[21] = pow(a[1]/b[15],2)*((b[8] - b[12])/b[15]);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sqrt( fft( a[2] * s + t * .25 ) ) * .4;
        c[1] = s * a[30];
        c[2] = c[0]*cos(c[1]) + b[ 3]*2 - 1;
        c[3] = c[0]*sin(c[1]) + b[ 4]*2 - 1;
        c[4] = c[0]*cos(c[1]) + b[ 7]*2 - 1;
        c[5] = c[0]*sin(c[1]) + b[ 8]*2 - 1;
        c[6] = c[0]*cos(c[1]) + b[11]*2 - 1;
        c[7] = c[0]*sin(c[1]) + b[12]*2 - 1;
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = c[4]; y[1] = c[5]; xyiMax = max(xyiMax, 1);
        x[2] = c[6]; y[2] = c[7]; xyiMax = max(xyiMax, 2);
        draw(1, 1, a[29], x, y, xyiMax);  // Meta() Reactive(3) Detail(4) Density(3) Morphable(1)
    }
}

