// ==============================================================================
void wave_Morphagon(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = t;
    a[1] = rnd( 2 * PI );
    a[2] = rnd( 2 * PI );
    a[3] = rnd( 2 * PI );
    a[4] = rnd( 2 * PI );
    a[5] = rnd( 2 * PI );
    a[6] = rnd( .008 ) + .004;
    a[7] = rnd( .008 ) + .004;
    a[8] = rnd( .008 ) + .004;
    a[9] = rnd( .008 ) + .004;
    a[10] = rnd( .008 ) + .004;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sqwv((t - a[0])*60);  // intitializer
    b[1] = 1 - b[0];
    b[2] = 1 - sqwv(b[6]*.75);  // object1
    b[3] = 1 - sqwv(b[7]);
    b[4] = b[4]*(1 - b[2])*b[1] - b[2]*abs(b[4])*sgn(b[6]) + b[0]*cos(a[1])*a[6];
    b[5] = b[5]*(1 - b[3])*b[1] - b[3]*abs(b[5])*sgn(b[7]) + b[0]*sin(a[1])*a[6];
    b[6] = b[6]*b[1] + b[4];
    b[7] = b[7]*b[1] + b[5];
    b[8] = 1 - sqwv(b[12]*.75);  // object2
    b[9] = 1 - sqwv(b[13]);
    b[10] = b[10]*(1 - b[8])*b[1] - b[8]*abs(b[10])*sgn(b[12]) + b[0]*cos(a[2])*a[7];
    b[11] = b[11]*(1 - b[9])*b[1] - b[9]*abs(b[11])*sgn(b[13]) + b[0]*sin(a[2])*a[7];
    b[12] = b[12]*b[1] + b[10];
    b[13] = b[13]*b[1] + b[11];
    b[14] = 1 - sqwv(b[18]*.75);  // object3
    b[15] = 1 - sqwv(b[19]);
    b[16] = b[16]*(1 - b[14])*b[1] - b[14]*abs(b[16])*sgn(b[18]) + b[0]*cos(a[3])*a[8];
    b[17] = b[17]*(1 - b[15])*b[1] - b[15]*abs(b[17])*sgn(b[19]) + b[0]*sin(a[3])*a[8];
    b[18] = b[18]*(1 - b[0]) + b[16];
    b[19] = b[19]*(1 - b[0]) + b[17];
    b[20] = 1 - sqwv(b[24]*.75);  // object4
    b[21] = 1 - sqwv(b[25]);
    b[22] = b[22]*(1 - b[20])*b[1] - b[20]*abs(b[22])*sgn(b[24]) + b[0]*cos(a[4])*a[9];
    b[23] = b[23]*(1 - b[21])*b[1] - b[21]*abs(b[23])*sgn(b[25]) + b[0]*sin(a[4])*a[9];
    b[24] = b[24]*b[1] + b[22];
    b[25] = b[25]*b[1] + b[23];
    b[26] = 1 - sqwv(b[30]*.75);  // object5
    b[27] = 1 - sqwv(b[31]);
    b[28] = b[28]*(1 - b[26])*b[1] - b[26]*abs(b[28])*sgn(b[30]) + b[0]*cos(a[5])*a[10];
    b[29] = b[29]*(1 - b[27])*b[1] - b[27]*abs(b[29])*sgn(b[31]) + b[0]*sin(a[5])*a[10];
    b[30] = b[30]*b[1] + b[28];
    b[31] = b[31]*b[1] + b[29];

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = mag( s * 12 ) * sin( s * PI ) * .1;
        x[0] = b[6]+s*(b[12]-b[6])-c[0]*(b[13]-b[7]); xyiMax = max(xyiMax, 0);
        y[0] = b[7]+s*(b[13]-b[7])+c[0]*(b[12]-b[6]);
        x[1] = b[6]+s*(b[18]-b[6])-c[0]*(b[19]-b[7]); xyiMax = max(xyiMax, 1);
        y[1] = b[7]+s*(b[19]-b[7])+c[0]*(b[18]-b[6]);
        x[2] = b[6]+s*(b[24]-b[6])-c[0]*(b[25]-b[7]); xyiMax = max(xyiMax, 2);
        y[2] = b[7]+s*(b[25]-b[7])+c[0]*(b[24]-b[6]);
        x[3] = b[6]+s*(b[30]-b[6])-c[0]*(b[31]-b[7]); xyiMax = max(xyiMax, 3);
        y[3] = b[7]+s*(b[31]-b[7])+c[0]*(b[30]-b[6]);
        x[4] = b[12]+s*(b[18]-b[12])-c[0]*(b[19]-b[13]); xyiMax = max(xyiMax, 4);
        y[4] = b[13]+s*(b[19]-b[13])+c[0]*(b[18]-b[12]);
        x[5] = b[12]+s*(b[24]-b[12])-c[0]*(b[25]-b[13]); xyiMax = max(xyiMax, 5);
        y[5] = b[13]+s*(b[25]-b[13])+c[0]*(b[24]-b[12]);
        x[6] = b[12]+s*(b[30]-b[12])-c[0]*(b[31]-b[13]); xyiMax = max(xyiMax, 6);
        y[6] = b[13]+s*(b[31]-b[13])+c[0]*(b[30]-b[12]);
        x[7] = b[18]+s*(b[24]-b[18])-c[0]*(b[25]-b[19]); xyiMax = max(xyiMax, 7);
        y[7] = b[19]+s*(b[25]-b[19])+c[0]*(b[24]-b[18]);
        x[8] = b[18]+s*(b[30]-b[18])-c[0]*(b[31]-b[19]); xyiMax = max(xyiMax, 8);
        y[8] = b[19]+s*(b[31]-b[19])+c[0]*(b[30]-b[18]);
        x[9] = b[24]+s*(b[30]-b[24])-c[0]*(b[31]-b[25]); xyiMax = max(xyiMax, 9);
        y[9] = b[25]+s*(b[31]-b[25])+c[0]*(b[30]-b[24]);
        draw(1, 1, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(5) Density(5) Morphable(5)
    }
}

// ==============================================================================
// Wave shape: Orbiting_Stars
// Macro:  Wave(Orbiting_Stars, "Ted", "", "", 1)
// Source: pixel/WaveShapes.sky.h:5077
// Author: Ted
// Steps=55  Aspect=0  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(4) Density(3) Morphable(3)
// ==============================================================================
void wave_Orbiting_Stars(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(55);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = t;
    a[1] = .09;
    a[2] = flor( rnd( 2 ) + 2 );  // Number of star points (*2)
    a[3] = rnd( .075 ) + .025;
    a[4] = .00025;
    a[5] = rnd( PI );
    a[6] = a[5] + rnd( 1 ) + .6;
    a[7] = a[6] + rnd( 1 ) + .6;
    a[8] = rnd( .6 ) + .5;  // initial positioning distances
    a[9] = rnd( .6 ) + .5;
    a[10] = rnd( .6 ) + .5;
    a[11] = rnd( 2 * PI );  // initial movement angles
    a[12] = rnd( 2 * PI );
    a[13] = rnd( 2 * PI );
    a[14] = rnd( 2 ) - 1;
    a[15] = rnd( 2 ) - 1;
    a[16] = rnd( 2 ) - 1;
    a[17] = a[ 8] * cos( a[ 5] );
    a[18] = a[ 8] * sin( a[ 5] );
    a[19] = a[ 9] * cos( a[ 6] );
    a[20] = a[ 9] * sin( a[ 6] );
    a[21] = a[10] * cos( a[ 7] );
    a[22] = a[10] * sin( a[ 7] );
    a[23] = a[14] * cos( a[11] );
    a[24] = a[14] * sin( a[11] );
    a[25] = a[15] * cos( a[12] );
    a[26] = a[15] * sin( a[12] );
    a[27] = a[16] * cos( a[13] );
    a[28] = a[16] * sin( a[13] );
    a[29] = .2 + rnd( .7 );
    a[30] = NumSSteps * PI;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = sqwv((t - a[0])*60);  // initializer
    b[1] = 1 - b[0];
    b[2] = b[1]*(b[ 2] + b[17]     + b[19]) + b[0]*a[23];  // movementvector
    b[3] = b[1]*(b[ 3] + b[18]     + b[20]) + b[0]*a[24];
    b[4] = b[1]* b[ 4] + b[ 0]*a[17] + a[ 4]*b[2];  // iterativeXpos
    b[5] = b[1]* b[ 5] + b[ 0]*a[18] + a[ 4]*b[3];  // iterativeYpos
    b[6] = b[1]*(b[ 6] - b[21]     - b[17]) + b[0]*a[25];
    b[7] = b[1]*(b[ 7] - b[22]     - b[18]) + b[0]*a[26];
    b[8] = b[1]* b[ 8] + b[ 0]*a[19] + a[ 4]*b[6];
    b[9] = b[1]* b[ 9] + b[ 0]*a[20] + a[ 4]*b[7];
    b[10] = b[1]*(b[10] + b[21]     - b[19]) + b[0]*a[27];
    b[11] = b[1]*(b[11] + b[22]     - b[20]) + b[0]*a[28];
    b[12] = b[1]* b[12] + b[ 0]*a[21] + a[ 4]*b[10];
    b[13] = b[1]* b[13] + b[ 0]*a[22] + a[ 4]*b[11];
    b[14] = sqrt(pow((b[ 8] - b[4]),2) + pow((b[ 9] - b[5]),2) + a[3]);  // distances
    b[15] = sqrt(pow((b[12] - b[4]),2) + pow((b[13] - b[5]),2) + a[3]);
    b[16] = sqrt(pow((b[12] - b[8]),2) + pow((b[13] - b[9]),2) + a[3]);
    b[17] = (pow(a[1]/b[14],2))*((b[ 8] - b[ 4])/b[14]);  // gravforce*cos[i.e.x/r]
    b[18] = (pow(a[1]/b[14],2))*((b[ 9] - b[ 5])/b[14]);  // gravforce*sin[i.e.y/r]
    b[19] = (pow(a[1]/b[15],2))*((b[12] - b[ 4])/b[15]);
    b[20] = (pow(a[1]/b[15],2))*((b[13] - b[ 5])/b[15]);
    b[21] = (pow(a[1]/b[16],2))*((b[ 8] - b[12])/b[16]);
    b[22] = (pow(a[1]/b[16],2))*((b[ 9] - b[13])/b[16]);
    b[23] = (b[4] + b[8] + b[12])/3;  // centeringonscreen
    b[24] = (b[5] + b[9] + b[13])/3;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = sqrt( fft( a[2] * s + t * .25 ) ) * .25;
        c[1] = s * a[30];
        c[2] = c[0] * cos( c[1] ) + b[4] - b[23];
        c[3] = c[0] * sin( c[1] ) + b[5] - b[24];
        c[4] = c[0] * cos( c[1] ) + b[8] - b[23];
        c[5] = c[0] * sin( c[1] ) + b[9] - b[24];
        c[6] = c[0] * cos( c[1] ) + b[12] - b[23];
        c[7] = c[0] * sin( c[1] ) + b[13] - b[24];
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = c[4]; y[1] = c[5]; xyiMax = max(xyiMax, 1);
        x[2] = c[6]; y[2] = c[7]; xyiMax = max(xyiMax, 2);
        x[3] = -c[2]; y[3] = -c[3]; xyiMax = max(xyiMax, 3);
        x[4] = -c[4]; y[4] = -c[5]; xyiMax = max(xyiMax, 4);
        x[5] = -c[6]; y[5] = -c[7]; xyiMax = max(xyiMax, 5);
        draw(1, 1, a[29], x, y, xyiMax);  // Meta() Reactive(3) Detail(4) Density(3) Morphable(3)
    }
}

