// ==============================================================================
void wave_Pinwheel(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = sgn(rnd(2)-1)*(rnd(5)+3);
    a[1] = sgn(rnd(2)-1);

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    // (no B() frame terms)

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = 1-trwv(s+t/a[0]);
        c[1] = fft(c[0])*1.5;
        c[2] = 1.6*s*a[1]*trwv(c[1]);
        c[3] = 1.6*s*trwv(c[1]-1)-.8;
        x[0] = c[2]; y[0] = c[3]; xyiMax = max(xyiMax, 0);
        x[1] = c[3]; y[1] = -c[2]; xyiMax = max(xyiMax, 1);
        x[2] = -c[2]; y[2] = -c[3]; xyiMax = max(xyiMax, 2);
        x[3] = -c[3]; y[3] = c[2]; xyiMax = max(xyiMax, 3);
        draw(1, c[0]*5, 1, x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: Psychloids_II
// Macro:  Wave(Psychloids_II, "Ted", "", "Cylinder Crown")  ... Num(2)
// Source: pixel/WaveShapes.sky.h:5237
// Author: Ted
// Note:   Cylinder Crown
// Steps=fftSlots()*flor(rnd(3)+3)  Aspect=1  Instances(num)=2
// Author metadata tags (unused by engine, informational): Meta() Reactive(5) Detail(4) Density(5) Morphable(4)
// NOTE(port): instance count set via Num(2) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Psychloids_II(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(fftSlots()*flor(rnd(3)+3));
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = NumSSteps / fftSlots();  // Number of points
    a[1] = rnd( .9 ) + .5;
    a[2] = flor( rnd( 1.999 ) );
    a[3] = a[2] * PI / ( a[0] - 1 );
    a[4] = .1 * ( 1 - a[2] ) + rnd(.25) + .04 * ( 4 - a[0] );
    a[5] = (.07 + rnd( .15 )) * sgn( rnd( 2 ) - 1 );
    a[6] = .3;  // * ( 1 / 3 - a[2] ))      // FFT direction and size
    a[7] = 1 / a[0];
    a[8] = a[0] - 1;
    a[9] = 2 * PI;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = a[5] * t + id * a[3];
    b[1] = b[0] /(a[0] / ( a[0] - 1 ) );
    b[2] = a[1] + a[4] * id;

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[9] * s + b[1];
        c[1] = trwv ( 1 - s * 2 * a[0] );
        c[2] = a[7] + a[6] * abs( fft( 1 - c[1] ) * c[1] );  // FFT calc
        x[0] = b[2]*((1 - c[2])*cos(c[0]) - (c[2])*cos(a[8]*(c[0] - b[0]))); xyiMax = max(xyiMax, 0);
        y[0] = b[2]*((1 - c[2])*sin(c[0]) + (c[2])*sin(a[8]*(c[0] - b[0])));
        draw(1, (c[1]*5-2), 1, x, y, xyiMax);  // Meta() Reactive(5) Detail(4) Density(5) Morphable(4)
    }
}

// ==============================================================================
// Wave shape: Rhythm_Guppies
// Macro:  Wave(Rhythm_Guppies, "Ted", "", "", 1)
// Source: pixel/WaveShapes.sky.h:5268
// Author: Ted
// Steps=fftSlots()  Aspect=0  Instances(num)=1
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(3) Density(3) Morphable(1)
// ==============================================================================
void wave_Rhythm_Guppies(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(fftSlots());
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = .3;
    a[1] = t;
    a[2] = 2 * PI;
    a[3] = rnd(.05)+.025;
    a[4] = clip( rnd( .5 ) + .6 );

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = beat() / 10 + .01;
    b[1] = sqwv( ( t - a[1] ) * 20 );
    b[2] = b[2] + rnd( a[0] ) - a[0] / 2 + b[1] * rnd( a[2] );  // movement vector
    b[3] = b[3] + b[0] * cos( b[2] );
    b[4] = b[4] + b[0] * sin( b[2] );
    b[5] = b[5] + rnd( a[0] ) - a[0] / 2 + b[1] * rnd( a[2]);  // repeat for next gupps
    b[6] = b[6] + b[0] * cos( b[5] );
    b[7] = b[7] + b[0] * sin( b[5] );
    b[8] = b[8] + rnd( a[0] ) - a[0] / 2 + b[1] * rnd( a[2] );
    b[9] = b[9] + b[0] * cos( b[8] );
    b[10] = b[10] + b[0] * sin( b[8] );
    b[11] = b[11] + rnd( a[0] ) - a[0] / 2 + b[1] * rnd( a[2] );
    b[12] = b[12] + b[0] * cos( b[11] );
    b[13] = b[13] + b[0] * sin( b[11] );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = ( s - .5 ) * .6;
        c[1] = .3 * fft( trwv( 1-2 * s ) ) + a[3];
        c[2] = a[2] * s + b[2];
        c[3] = a[2] * s + b[5];
        c[4] = a[2] * s + b[8];
        c[5] = a[2] * s + b[11];
        x[0] = saw(c[1]*cos(c[2])+b[ 3]+1); y[0] = saw(c[1]*sin(c[2])+b[ 4]+1); xyiMax = max(xyiMax, 0);
        x[1] = saw(c[1]*cos(c[3])+b[ 6]+1); y[1] = saw(c[1]*sin(c[3])+b[ 7]+1); xyiMax = max(xyiMax, 1);
        x[2] = saw(c[1]*cos(c[4])+b[ 9]+1); y[2] = saw(c[1]*sin(c[4])+b[10]+1); xyiMax = max(xyiMax, 2);
        x[3] = saw(c[1]*cos(c[5])+b[12]+1); y[3] = saw(c[1]*sin(c[5])+b[13]+1); xyiMax = max(xyiMax, 3);
        draw(0, 3, a[4], x, y, xyiMax);  // Meta() Reactive(3) Detail(3) Density(3) Morphable(1)
    }
}

