// Wave shape: Rosette
// Macro:  Wave(Rosette, "Ted", "", "Three's a Crowd,Hollow Horizontal ")  ... Num(trnc(rnd(2.99)+3)*2)
// Source: pixel/WaveShapes.sky.h:5319
// Author: Ted
// Note:   Three's a Crowd,Hollow Horizontal 
// Steps=sampleSlots()/2  Aspect=1  Instances(num)=trnc(rnd(2.99)+3)*2
// Author metadata tags (unused by engine, informational): Meta() Reactive(3) Detail(4) Density(4) Morphable(4)
// NOTE(port): instance count set via Num(trnc(rnd(2.99)+3)*2) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Rosette(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(sampleSlots()/2);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = PI * 2;
    a[1] = 2 * a[0] / num;
    a[2] = trnc( rnd( 1.999 ) + 1 );
    a[3] = 4 + rnd( 8 );
    a[4] = a[3] * ( rnd( 1 / 3 ) + 1 / 3 );
    a[5] = trnc( rnd( 2 ) );
    a[6] = flor( rnd( 3 ) ) - 1;
    a[7] = PI * a[2];
    a[8] = PI * ( a[2] / 2 - 1 );
    a[9] = trnc( rnd( 1.99 ) );
    a[10] = ( 1 - a[9] ) * .157;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = t * 0.25;
    b[1] = trnc( id / 2 );
    b[3] = log( 5 * beat() + 1 ) * a[9] * .055;
    b[4] = ( .3 + a[6] * b[3] ) * cos( b[0] + b[1] * a[1]);
    b[5] = ( .3 + a[6] * b[3] ) * sin( b[0] + b[1] * a[1]);
    b[6] = .314 + b[3];
    b[8] = b[0]+b[1]*a[1];
    b[9] = fmod(id+a[5],2);
    b[10] = a[4]*fmod(id     ,2);

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = abs(sin(a[7]*s+a[8]));
        c[1] = b[6]+a[10]*mag(s*2)*c[0];
        c[2] = s*a[0]+b[8];
        x[0] = c[1]*cos(c[2])+b[4]; xyiMax = max(xyiMax, 0);
        y[0] = c[1]*sin(c[2])+b[5];
        draw(1, a[3]*c[0]-b[10], b[9], x, y, xyiMax);  // Meta() Reactive(3) Detail(4) Density(4) Morphable(4)
    }
}

