        double s = (double)sint / (double)steps;
        c[0] = .97*s;
        c[1] = atan( 3 * fft(1- s) )*.6;  // Changed for loud audio -- ACO 5 APR 04
        c[2] = c[1]+t*a[0];
        c[3] = c[1]-t*a[0];
        x[0] = c[0]*sin(c[3]     ); y[0] = c[0]*cos(c[3]     ); xyiMax = max(xyiMax, 0);
