// Wave shape: Trance_Snap
// Macro:  Wave(Trance_Snap, "Ted", "", "")  ... Num(flor(  rnd(  1.11111  )  )  +  1)
// Source: pixel/WaveShapes.sky.h:5542
// Author: Ted
// Steps=512  Aspect=1  Instances(num)=flor(  rnd(  1.11111  )  )  +  1
// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(3) Morphable(1)
// NOTE(port): instance count set via Num(flor(  rnd(  1.11111  )  )  +  1) macro, not Wave()'s 5th argument
// ==============================================================================
void wave_Trance_Snap(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(512);
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (1);
    a[0] = 2 * PI;
    a[1] = .8;
    a[2] = 2 - a[1];
    a[3] = a[2] / 2;
    a[4] = .6 + rnd( .4 );
    a[5] = rnd( 1 );
    a[6] = .8;

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    b[0] = b[0] + b[1] * ( 1 - sqwv( a[6] * log( 5 * beat() + 1 ) ) );
    b[1] = sqwv( a[6] * log( 5 * beat() + 1 ) );
    b[2] = seed( trnc( b[0] / 4 ) + a[5] );
    b[3] = rnd( a[0] );
    b[4] = cos( b[3] );
    b[5] = sin( b[3] );
    b[6] = rnd( a[2] ) - a[3];
    b[7] = rnd( a[2] ) - a[3];
    b[8] = b[7] * b[4] / ( 1 - 4 * id );
    b[9] = b[7] * b[5] / ( 1 - 4 * id );

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = a[1] * ( s - .5 ) + b[6];
        c[1] = a[1] * fft( trwv( 1.98 * s - .99 ) );
        c[2] = b[4] * c[0] + b[5] * c[1] + b[9];
        c[3] = b[4] * c[0] - b[5] * c[1] + b[9];
        c[4] = b[5] * c[0] - b[4] * c[1] - b[8];
        c[5] = b[5] * c[0] + b[4] * c[1] - b[8];
        x[0] = c[2]; y[0] = c[4]; xyiMax = max(xyiMax, 0);
        x[1] = c[3]; y[1] = c[5]; xyiMax = max(xyiMax, 1);
        x[2] = -c[2]; y[2] = -c[4]; xyiMax = max(xyiMax, 2);
        x[3] = -c[3]; y[3] = -c[5]; xyiMax = max(xyiMax, 3);
        draw(1, 1, a[4], x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(3) Morphable(1)// Because this config jumps around) it makes a nasty morph.
    }
}

