// Author metadata tags (unused by engine, informational): Meta() Reactive(4) Detail(4) Density(4) Morphable(5)
// ==============================================================================
void wave_Walls_of_Sound(WaveVars* wv, double id, double num, double t,
                   double ux, double uy, double ur, double ua, DrawFn draw)
// NOTE(port): id and num are double (not int) -- matches WaveShape class
// members in pixel/Waveshapes.cpp (`double s,si,aspect,num,id;`), which
// matters because many shapes divide by them (e.g. `id/num`) expecting a
// floating-point fraction rather than integer division.
{
    double *a = wv->a, *b = wv->b, *c = wv->c, *x = wv->x, *y = wv->y;
    int xyiMax = 0;

    // ---- setup: evaluated ONCE per instance, when this shape is selected ----
    int    steps  = (int)(fftSlots());
    if (steps == -1) steps = 300;  // Steps(-1) sentinel (pixel/Waveshapes.cpp Steps macro)
    double aspect = (0);
    a[0] = sgn(rnd(2)-1)*( rnd(.12) + .03 );
    a[1] = rnd(.4)+.55;
    a[2] = pow(a[1],2);
    a[3] = pow(a[1],3);
    a[4] = pow(a[1],4);
    a[5] = pow(a[1],5);

    // ---- frame: evaluated ONCE PER RENDERED FRAME, per instance ----
    // (no B() frame terms)

    // ---- pixel: evaluated once per step s in [0,1], `steps` subdivisions ----
    // (real engine: nested loop `for id in [0,num)` x `for sint in [0,steps]`;
    //  this function represents the BODY for one (id, s) pair -- caller loops s.
    //  Real engine accumulates s += 1/steps each iteration (ForSteps macro);
    //  recomputed here as sint/steps, numerically equivalent modulo float drift.)
    for (int sint = 0; sint <= steps; sint++)
    {
        double s = (double)sint / (double)steps;
        c[0] = (3*s-1.5);
        c[1] = fft( s+t*a[0] )*.8-.8;
        x[0] = c[1]; y[0] = c[0]; xyiMax = max(xyiMax, 0);
        x[1] = -c[1]; y[1] = c[0]; xyiMax = max(xyiMax, 1);
        x[2] = c[1]*a[1]; y[2] = c[0]*a[1]; xyiMax = max(xyiMax, 2);
        x[3] = -c[1]*a[1]; y[3] = c[0]*a[1]; xyiMax = max(xyiMax, 3);
        x[4] = c[1]*a[2]; y[4] = c[0]*a[2]; xyiMax = max(xyiMax, 4);
        x[5] = -c[1]*a[2]; y[5] = c[0]*a[2]; xyiMax = max(xyiMax, 5);
        x[6] = c[1]*a[3]; y[6] = c[0]*a[3]; xyiMax = max(xyiMax, 6);
        x[7] = -c[1]*a[3]; y[7] = c[0]*a[3]; xyiMax = max(xyiMax, 7);
        x[8] = c[1]*a[4]; y[8] = c[0]*a[4]; xyiMax = max(xyiMax, 8);
        x[9] = -c[1]*a[4]; y[9] = c[0]*a[4]; xyiMax = max(xyiMax, 9);
        x[10] = c[1]*a[5]; y[10] = c[0]*a[5]; xyiMax = max(xyiMax, 10);
        x[11] = -c[1]*a[5]; y[11] = c[0]*a[5]; xyiMax = max(xyiMax, 11);
        draw(1, 1, pow(1-(1-sin( s * PI )),4), x, y, xyiMax);  // Meta() Reactive(4) Detail(4) Density(4) Morphable(5)
    }
}
